-- Catalog v3 includes the same starter content shown during selection. Preserve customized versions.
UPDATE "Template" SET version=3, config='{"schemaVersion": 1, "background": "#ffffff", "foreground": "#111827", "accent": "#111827", "initialBlocks": [{"id": "00000000-0000-4000-8000-000000000001", "type": "button", "visible": true, "label": "Visit Website", "url": "https://example.com", "icon": "globe"}, {"id": "00000000-0000-4000-8000-000000000002", "type": "link", "visible": true, "label": "Latest Projects", "url": "https://example.com", "icon": "globe"}, {"id": "00000000-0000-4000-8000-000000000003", "type": "link", "visible": true, "label": "Book a Call", "url": "https://example.com", "icon": "globe"}, {"id": "00000000-0000-4000-8000-000000000004", "type": "social", "visible": true, "items": [{"label": "Instagram", "url": "https://instagram.com"}, {"label": "X", "url": "https://x.com"}, {"label": "LinkedIn", "url": "https://linkedin.com"}]}], "appearance": "aurora", "initialProfile": {"name": "Rock Agency", "bio": "Digital agency specializing in SaaS products.", "avatarPreset": "agency"}}'::jsonb, "updatedAt"=NOW() WHERE key='basic' AND version=2;
