-- Repair only untouched, unpublished onboarding drafts with the exact old empty defaults.
-- Never overwrite edits, published pages, personal profiles, photos, or existing blocks.
UPDATE "Page" p SET
 draft=jsonb_build_object('schemaVersion',1,'profile',t.config->'initialProfile','blocks',
  (SELECT jsonb_agg(b || jsonb_build_object('id',gen_random_uuid()::text)) FROM jsonb_array_elements(t.config->'initialBlocks') b)),
 "templateConfig"=t.config, "templateVersion"=t.version, revision=p.revision+1, "updatedAt"=NOW()
FROM "Template" t WHERE p."templateKey"=t.key AND t.version=3
 AND t.key IN ('basic','sunset','mint','pixel') AND p."templateVersion" IN (1,2)
 AND p.revision=1 AND p."publishedVersionId" IS NULL
 AND p.draft=jsonb_build_object('schemaVersion',1,'profile',jsonb_build_object('name','Meu Catlink','bio',''),'blocks','[]'::jsonb)
 AND NOT EXISTS (SELECT 1 FROM "PublishedVersion" v WHERE v."pageId"=p.id)
 AND EXISTS (SELECT 1 FROM "Onboarding" o WHERE o."completedPageId"=p.id);
